        impl LzmaOptions { # [doc = " Creates a new blank set of options for encoding."] # [doc = ""] # [doc = " The `preset` argument is the compression level to use, typically in the"] # [doc = " range of 0-9."] pub fn new_preset (preset : u32) -> Result < LzmaOptions , Error > { unsafe { let mut options = LzmaOptions { raw : mem :: zeroed () } ; let ret = lzma_sys :: lzma_lzma_preset (& mut options . raw , preset) ; if ret != 0 { Err (Error :: Program) } else { Ok (options) } } } # [doc = " Configures the dictionary size, in bytes"] # [doc = ""] # [doc = " Dictionary size indicates how many bytes of the recently processed"] # [doc = " uncompressed data is kept in memory."] # [doc = ""] # [doc = " The minimum dictionary size is 4096 bytes and the default is 2^23, 8MB."] pub fn dict_size (& mut self , size : u32) -> & mut LzmaOptions { self . raw . dict_size = size ; self } # [doc = " Configures the number of literal context bits."] # [doc = ""] # [doc = " How many of the highest bits of the previous uncompressed eight-bit byte"] # [doc = " (also known as `literal') are taken into account when predicting the"] # [doc = " bits of the next literal."] # [doc = ""] # [doc = " The maximum value to this is 4 and the default is 3. It is not currently"] # [doc = " supported if this plus `literal_position_bits` is greater than 4."] pub fn literal_context_bits (& mut self , bits : u32) -> & mut LzmaOptions { self . raw . lc = bits ; self } # [doc = " Configures the number of literal position bits."] # [doc = ""] # [doc = " This affects what kind of alignment in the uncompressed data is assumed"] # [doc = " when encoding literals. A literal is a single 8-bit byte. See"] # [doc = " `position_bits` for more information about alignment."] # [doc = ""] # [doc = " The default for this is 0."] pub fn literal_position_bits (& mut self , bits : u32) -> & mut LzmaOptions { self . raw . lp = bits ; self } # [doc = " Configures the number of position bits."] # [doc = ""] # [doc = " Position bits affects what kind of alignment in the uncompressed data is"] # [doc = " assumed in general. The default of 2 means four-byte alignment (2^ pb"] # [doc = " =2^2=4), which is often a good choice when there's no better guess."] # [doc = ""] # [doc = " When the aligment is known, setting pb accordingly may reduce the file"] # [doc = " size a little. E.g. with text files having one-byte alignment (US-ASCII,"] # [doc = " ISO-8859-*, UTF-8), setting pb=0 can improve compression slightly. For"] # [doc = " UTF-16 text, pb=1 is a good choice. If the alignment is an odd number"] # [doc = " like 3 bytes, pb=0 might be the best choice."] # [doc = ""] # [doc = " Even though the assumed alignment can be adjusted with pb and lp, LZMA1"] # [doc = " and LZMA2 still slightly favor 16-byte alignment. It might be worth"] # [doc = " taking into account when designing file formats that are likely to be"] # [doc = " often compressed with LZMA1 or LZMA2."] pub fn position_bits (& mut self , bits : u32) -> & mut LzmaOptions { self . raw . pb = bits ; self } # [doc = " Configures the compression mode."] pub fn mode (& mut self , mode : Mode) -> & mut LzmaOptions { self . raw . mode = mode as lzma_sys :: lzma_mode ; self } # [doc = " Configures the nice length of a match."] # [doc = ""] # [doc = " This determines how many bytes the encoder compares from the match"] # [doc = " candidates when looking for the best match. Once a match of at least"] # [doc = " `nice_len` bytes long is found, the encoder stops looking for better"] # [doc = " candidates and encodes the match. (Naturally, if the found match is"] # [doc = " actually longer than `nice_len`, the actual length is encoded; it's not"] # [doc = " truncated to `nice_len`.)"] # [doc = ""] # [doc = " Bigger values usually increase the compression ratio and compression"] # [doc = " time. For most files, 32 to 128 is a good value, which gives very good"] # [doc = " compression ratio at good speed."] # [doc = ""] # [doc = " The exact minimum value depends on the match finder. The maximum is 273,"] # [doc = " which is the maximum length of a match that LZMA1 and LZMA2 can encode."] pub fn nice_len (& mut self , len : u32) -> & mut LzmaOptions { self . raw . nice_len = len ; self } # [doc = " Configures the match finder ID."] pub fn match_finder (& mut self , mf : MatchFinder) -> & mut LzmaOptions { self . raw . mf = mf as lzma_sys :: lzma_match_finder ; self } # [doc = " Maximum search depth in the match finder."] # [doc = ""] # [doc = " For every input byte, match finder searches through the hash chain or"] # [doc = " binary tree in a loop, each iteration going one step deeper in the chain"] # [doc = " or tree. The searching stops if"] # [doc = ""] # [doc = "  - a match of at least `nice_len` bytes long is found;"] # [doc = "  - all match candidates from the hash chain or binary tree have"] # [doc = "    been checked; or"] # [doc = "  - maximum search depth is reached."] # [doc = ""] # [doc = " Maximum search depth is needed to prevent the match finder from wasting"] # [doc = " too much time in case there are lots of short match candidates. On the"] # [doc = " other hand, stopping the search before all candidates have been checked"] # [doc = " can reduce compression ratio."] # [doc = ""] # [doc = " Setting depth to zero tells liblzma to use an automatic default value,"] # [doc = " that depends on the selected match finder and nice_len.  The default is"] # [doc = " in the range [4, 200] or so (it may vary between liblzma versions)."] # [doc = ""] # [doc = " Using a bigger depth value than the default can increase compression"] # [doc = " ratio in some cases. There is no strict maximum value, but high values"] # [doc = " (thousands or millions) should be used with care: the encoder could"] # [doc = " remain fast enough with typical input, but malicious input could cause"] # [doc = " the match finder to slow down dramatically, possibly creating a denial"] # [doc = " of service attack."] pub fn depth (& mut self , depth : u32) -> & mut LzmaOptions { self . raw . depth = depth ; self } }
